BEGIN TRANSACTION;
CREATE TABLE IF NOT EXISTS "dim_customer" (
	"customer_key"	INTEGER,
	"customer_id"	INTEGER,
	"customer_name"	TEXT,
	"email"	TEXT,
	"city"	TEXT,
	"region"	TEXT,
	"segment"	TEXT,
	"joined_on"	TEXT
);
CREATE TABLE IF NOT EXISTS "dim_date" (
	"date_key"	INTEGER,
	"date"	TEXT,
	"year"	INTEGER,
	"quarter"	INTEGER,
	"month"	INTEGER,
	"month_name"	TEXT,
	"week_of_year"	INTEGER,
	"day_of_month"	INTEGER,
	"day_of_week"	INTEGER,
	"day_name"	TEXT,
	"is_weekend"	TEXT,
	"is_holiday"	TEXT,
	"holiday_name"	TEXT,
	"fiscal_year"	INTEGER,
	"fiscal_quarter"	INTEGER
);
CREATE TABLE IF NOT EXISTS "dim_product" (
	"product_key"	INTEGER,
	"product_id"	INTEGER,
	"product_name"	TEXT,
	"category"	TEXT,
	"subcategory"	TEXT,
	"brand"	TEXT,
	"unit_cost"	REAL,
	"list_price"	REAL
);
CREATE TABLE IF NOT EXISTS "dim_store" (
	"store_key"	INTEGER,
	"store_id"	INTEGER,
	"store_name"	TEXT,
	"city"	TEXT,
	"region"	TEXT,
	"store_type"	TEXT,
	"opened_on"	TEXT
);
CREATE TABLE IF NOT EXISTS "fact_sales" (
	"sale_id"	INTEGER,
	"customer_key"	INTEGER,
	"store_key"	INTEGER,
	"product_key"	INTEGER,
	"date_key"	INTEGER,
	"time_of_day"	TEXT,
	"category"	TEXT,
	"quantity"	REAL,
	"discount_pct"	REAL,
	"revenue"	REAL,
	"unit_price"	REAL
);
COMMIT;
